const vacancy = { ...$json };

function normalizeText(value) {
  return String(value || "")
    .replace(/\u00a0/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\s+([,.;:!?])/g, "$1")
    .trim();
}

function normalizeExistingWorkFormat(currentValue, descriptionValue) {
  const current = normalizeText(currentValue).toLowerCase();
  const description = normalizeText(descriptionValue).toLowerCase();

  if (
    /работа только в офисе|только офисный формат|удал[её]нного формата нет|удал[её]нной работы нет|удал[её]нно работать нельзя/.test(
      description
    )
  ) {
    return "office";
  }

  if (
    /разъездн(?:ая|ой|ую)\s+работ|выезжать к клиентам|выездн(?:ая|ой|ые)\s+работ|установка оборудования.*у клиент/.test(
      description
    )
  ) {
    return "field";
  }

  if (
    /гибридн(?:ая|ый|ое|ом)\s+(?:работа|формат)|частично удал[её]нн|несколько дней в офисе/.test(
      description
    )
  ) {
    return "hybrid";
  }

  if (
    /удал[её]нн(?:ая|ый|ое|ой)\s+(?:работа|формат)|работа\s+удал[её]нно|полностью удал[её]нн/.test(
      description
    )
  ) {
    return "remote";
  }

  const allowedCurrentValues = new Set([
    "remote",
    "hybrid",
    "office",
    "field",
    "unspecified",
  ]);

  if (allowedCurrentValues.has(current)) {
    return current;
  }

  return "unspecified";
}

vacancy.work_format = normalizeExistingWorkFormat(
  vacancy.work_format,
  vacancy.description_text
);

vacancy.updated_at = new Date().toISOString();

return {
  json: vacancy,
};

const vacancy = { ...$json };

const title = String(vacancy.title || "")
  .replace(/\s+/g, " ")
  .trim();

const description = String(vacancy.description_text || "")
  .replace(/\s+/g, " ")
  .trim();

const reasons = [];

const titleBlockers = [
  {
    code: "sales_role",
    pattern:
      /менеджер по продажам|руководитель продаж|sales manager|account manager|аккаунт-менеджер|business development|менеджер по работе с партнерами|менеджер по работе с клиентами/i,
  },
  {
    code: "marketing_seo_role",
    pattern:
      /маркетолог|media buyer|медиабайер|контекстн(?:ая|ой)\s+реклам|seo[- /]|seo специалист|seo-специалист|seo developer|community manager|контент[- ]менеджер|руководитель.*\bpr\b/i,
  },
  {
    code: "assistant_role",
    pattern:
      /ассистент руководителя|помощник руководителя|бизнес-ассистент|личный ассистент/i,
  },
  {
    code: "project_product_role",
    pattern:
      /project manager|product manager|project\/product manager|руководитель проектов|менеджер проектов|проджект[- ]менеджер|продакт[- ]менеджер/i,
  },
  {
    code: "recruiting_role",
    pattern:
      /рекрутер|hr[- ]менеджер|hr manager|менеджер по персоналу|специалист по подбору персонала/i,
  },
  {
    code: "qa_testing_role",
    pattern:
      /\baqa\b|\bqa\b|quality assurance|automation qa|qa automation|тестировщик|тестировани[ея]|автоматизатор тестирования|инженер по автоматизации тестирования|sdet/i,
  },
  {
    code: "ml_ds_role",
    pattern:
      /machine learning|\bml[- /]|ml engineer|ml-инженер|ml\/ds|data scientist|data science|ds инженер|инженер машинного обучения|разработчик искусственного интеллекта|разработчик рекомендательной системы/i,
  },
  {
    code: "pure_software_development",
    pattern:
      /fullstack|full-stack|frontend|front-end|backend|back-end|php[- ]разработчик|java[- ]разработчик|golang[- ]разработчик|разработчик c\+\+|data engineer|data-инженер|dwh engineer/i,
  },
  {
    code: "industrial_automation_role",
    pattern:
      /асу\s*тп|асутп|кипиа|кип и а|\bplc\b|плк|\bscada\b|автоматизаци[яи] технологических процессов|автоматизаци[яи] производства|инженер пнр/i,
  },
  {
    code: "industrial_engineering_role",
    pattern:
      /инженер-технолог|ведущий инженер-технолог|инженер-конструктор|инженер-схемотехник|инженер-испытатель|монтажник рэа|электрооборудовани[юя].*автоматизаци|инженер-проектировщик.*эом|инженер производственного склада/i,
  },
  {
    code: "one_c_development_role",
    pattern:
      /программист\s*1с|разработчик\s*1с|1с[- ]разработчик/i,
  },
  {
    code: "non_it_role",
    pattern:
      /курьер|водитель|кладовщик|комплектовщик|повар|продавец-консультант|ведущий юрист|менеджер по логистике|методолог образовательных программ|эксплуатаци[яи] и ремонт.*помещени/i,
  },
  {
    code: "computer_club_role",
    pattern:
      /администратор компьютерного клуба/i,
  },
  {
    code: "traffic_arbitrage_role",
    pattern:
      /traffic arbitrage|traffic buyer|арбитраж трафика/i,
  },
];

for (const blocker of titleBlockers) {
  if (blocker.pattern.test(title)) {
    reasons.push(blocker.code);
  }
}

if (!vacancy.vacancy_id) {
  reasons.push("missing_vacancy_id");
}

if (!vacancy.url) {
  reasons.push("missing_url");
}

if (!title) {
  reasons.push("missing_title");
}

if (!description || description.length < 200) {
  reasons.push("insufficient_description");
}

const parseFailureReasons = new Set([
  "missing_vacancy_id",
  "missing_url",
  "missing_title",
  "insufficient_description",
]);

const hasParseFailure = reasons.some((reason) =>
  parseFailureReasons.has(reason)
);

if (hasParseFailure) {
  vacancy.status = "parse_failed";
} else if (reasons.length > 0) {
  vacancy.status = "filtered";
} else {
  vacancy.status = "found";
}

vacancy.filter_reason = reasons.join(",");
vacancy.updated_at = new Date().toISOString();

if (vacancy.status === "parse_failed" && !vacancy.last_error) {
  vacancy.last_error =
    "Required vacancy data is missing or incomplete";
}

return {
  json: vacancy,
};

const items = $input.all();

const summary = {
  total: items.length,
  found: 0,
  filtered: 0,
  parse_failed: 0,
  other: 0,
  work_format: {
    remote: 0,
    hybrid: 0,
    office: 0,
    field: 0,
    unspecified: 0,
    other: 0,
  },
  filter_reasons: {},
};

for (const item of items) {
  const vacancy = item.json;
  const status = String(vacancy.status || "");
  const workFormat = String(
    vacancy.work_format || "unspecified"
  );

  if (
    status === "found" ||
    status === "filtered" ||
    status === "parse_failed"
  ) {
    summary[status] += 1;
  } else {
    summary.other += 1;
  }

  if (
    Object.prototype.hasOwnProperty.call(
      summary.work_format,
      workFormat
    )
  ) {
    summary.work_format[workFormat] += 1;
  } else {
    summary.work_format.other += 1;
  }

  const reasons = String(vacancy.filter_reason || "")
    .split(",")
    .map((value) => value.trim())
    .filter(Boolean);

  for (const reason of reasons) {
    summary.filter_reasons[reason] =
      (summary.filter_reasons[reason] || 0) + 1;
  }
}

summary.filter_reasons = Object.fromEntries(
  Object.entries(summary.filter_reasons)
    .sort((left, right) => right[1] - left[1])
);

return [
  {
    json: summary,
  },
];

function parseSalaryAmount(rawValue, hasThousands) {
  let number = Number(
    String(rawValue || "")
      .replace(/\u00a0/g, " ")
      .replace(/\s/g, "")
      .replace(",", ".")
  );

  if (!Number.isFinite(number)) {
    return null;
  }

  if (hasThousands && number < 1000) {
    number *= 1000;
  }

  if (number < 10000 || number > 2000000) {
    return null;
  }

  return Math.round(number);
}

function extractUpperBounds(text) {
  const source = String(text || "")
    .replace(/\u00a0/g, " ")
    .toLowerCase();

  const values = [];

  const rangePattern =
    /(\d[\d\s]*(?:[.,]\d+)?)\s*(тыс(?:\.|яч[аи])?|[кk])?\s*(?:-|–|—|до)\s*(\d[\d\s]*(?:[.,]\d+)?)\s*(тыс(?:\.|яч[аи])?|[кk])?(?:\s*(?:руб(?:\.|ля|лей)?|rur)|\s*₽)?/gi;

  for (const match of source.matchAll(rangePattern)) {
    const hasThousands = Boolean(match[2] || match[4]);

    const upper = parseSalaryAmount(
      match[3],
      Boolean(match[4]) || hasThousands
    );

    if (upper !== null) {
      values.push(upper);
    }
  }

  const upperLimitPattern =
    /(?:до|максимум|max)\s*(\d[\d\s]*(?:[.,]\d+)?)\s*(тыс(?:\.|яч[аи])?|[кk])?(?:\s*(?:руб(?:\.|ля|лей)?|rur)|\s*₽)?/gi;

  for (
    const match of source.matchAll(upperLimitPattern)
  ) {
    const upper = parseSalaryAmount(
      match[1],
      Boolean(match[2])
    );

    if (upper !== null) {
      values.push(upper);
    }
  }

  return values;
}

function extractSalaryContexts(descriptionValue) {
  const description = String(descriptionValue || "")
    .replace(/\u00a0/g, " ")
    .replace(/\s+/g, " ")
    .toLowerCase();

  const markerPattern =
    /зарплат|заработн|оклад|доход|оплат[аы]|вознагражден|вилк/gi;

  const contexts = [];

  for (
    const match of description.matchAll(markerPattern)
  ) {
    const start = Math.max(0, match.index - 60);
    const end = Math.min(
      description.length,
      match.index + 220
    );

    contexts.push(
      description.slice(start, end)
    );
  }

  return contexts;
}

function extractKnownSalaryUpperBound(
  salaryValue,
  descriptionValue
) {
  const salary = String(salaryValue || "")
    .replace(/\u00a0/g, " ")
    .replace(/\s+/g, " ")
    .toLowerCase()
    .trim();

  const salaryIsUnknown =
    !salary ||
    /не указана|не указано|по договор[её]нности/.test(
      salary
    );

  if (!salaryIsUnknown) {
    if (
      /usd|eur|доллар|евро|тенге|₸|\$|€/.test(
        salary
      ) &&
      !/(?:руб|₽|rur)/.test(salary)
    ) {
      return null;
    }

    if (
      /в час|за час|в день|за день|в неделю|за неделю/.test(
        salary
      )
    ) {
      return null;
    }

    const isLowerBoundOnly =
      /^\s*от\s*\d/i.test(salary) &&
      !/до\s*\d/i.test(salary) &&
      !/(?:-|–|—)\s*\d/i.test(salary);

    if (isLowerBoundOnly) {
      return null;
    }

    const structuredBounds =
      extractUpperBounds(salary);

    if (structuredBounds.length > 0) {
      return Math.max(...structuredBounds);
    }

    const fixedPattern =
      /(\d[\d\s]*(?:[.,]\d+)?)\s*(тыс(?:\.|яч[аи])?|[кk])?(?:\s*(?:руб(?:\.|ля|лей)?|rur)|\s*₽)/gi;

    const fixedValues = [];

    for (
      const match of salary.matchAll(fixedPattern)
    ) {
      const fixed = parseSalaryAmount(
        match[1],
        Boolean(match[2])
      );

      if (fixed !== null) {
        fixedValues.push(fixed);
      }
    }

    return fixedValues.length > 0
      ? Math.max(...fixedValues)
      : null;
  }

  const descriptionBounds = [];

  for (
    const context of extractSalaryContexts(
      descriptionValue
    )
  ) {
    descriptionBounds.push(
      ...extractUpperBounds(context)
    );
  }

  return descriptionBounds.length > 0
    ? Math.max(...descriptionBounds)
    : null;
}

function parseAnalysis(value) {
  if (value && typeof value === "object") {
    return value;
  }

  if (typeof value !== "string" || !value.trim()) {
    return null;
  }

  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

function normalizeList(value) {
  return Array.isArray(value)
    ? value
        .map((entry) => String(entry || "").trim())
        .filter(Boolean)
    : [];
}

function calculateBaseScore(evaluation) {
  const breakdown =
    evaluation.score_breakdown &&
    typeof evaluation.score_breakdown === "object"
      ? evaluation.score_breakdown
      : {};

  const values = [
    Number(breakdown.role_fit),
    Number(breakdown.skills_fit),
    Number(breakdown.evidence_strength),
    Number(breakdown.conditions_fit),
  ];

  if (!values.every(Number.isFinite)) {
    const fallback = Number(evaluation.score);
    return Number.isFinite(fallback) ? fallback : 0;
  }

  return values.reduce(
    (total, value) => total + value,
    0
  );
}

function calculateDecision(score) {
  if (score >= 75) {
    return "recommend";
  }

  if (score >= 60) {
    return "review";
  }

  return "reject";
}

const minimumNetSalary = {
  ai_automation: 120000,
  it_infrastructure: 100000,
};

const deterministicSalaryRiskPattern =
  /^Максимальная указанная зарплата \d+ руб\. ниже минимального порога \d+ руб\. на руки$/;

const output = [];

for (const item of $input.all()) {
  const vacancy = { ...item.json };
  const analysis = parseAnalysis(
    vacancy.analysis_json
  );

  if (!analysis) {
    continue;
  }

  const evaluation =
    analysis.evaluation &&
    typeof analysis.evaluation === "object"
      ? { ...analysis.evaluation }
      : null;

  if (!evaluation) {
    continue;
  }

  const recommendedResume = String(
    vacancy.recommended_resume ||
    evaluation.recommended_resume ||
    "none"
  );

  const threshold =
    minimumNetSalary[recommendedResume] || null;

  if (threshold === null) {
    continue;
  }

  const salaryUpperBound =
    extractKnownSalaryUpperBound(
      vacancy.salary,
      vacancy.description_text
    );

  let blockingReasons = normalizeList(
    evaluation.blocking_reasons
  );

  let riskFlags = normalizeList(
    evaluation.risk_flags
  );

  const hadSalaryBlock =
    blockingReasons.includes(
      "salary_below_minimum"
    );

  const shouldHaveSalaryBlock =
    salaryUpperBound !== null &&
    salaryUpperBound < threshold;

  if (
    hadSalaryBlock === shouldHaveSalaryBlock
  ) {
    continue;
  }

  let baseScore = calculateBaseScore(evaluation);

  if (evaluation.critical_gap === true) {
    baseScore = Math.min(baseScore, 59);
  }

  let action;

  if (shouldHaveSalaryBlock) {
    action = "salary_block_applied";

    blockingReasons.push(
      "salary_below_minimum"
    );

    const salaryRisk =
      `Максимальная указанная зарплата ` +
      `${salaryUpperBound} руб. ниже минимального ` +
      `порога ${threshold} руб. на руки`;

    if (!riskFlags.includes(salaryRisk)) {
      riskFlags.push(salaryRisk);
    }

    evaluation.score = Math.min(
      baseScore,
      59
    );
    evaluation.decision = "reject";
    evaluation.cover_letter_recommended = false;
  } else {
    action = "salary_block_removed";

    blockingReasons = blockingReasons.filter(
      (reason) =>
        reason !== "salary_below_minimum"
    );

    riskFlags = riskFlags.filter(
      (risk) =>
        !deterministicSalaryRiskPattern.test(risk)
    );

    evaluation.score = baseScore;
    evaluation.decision =
      calculateDecision(baseScore);
    evaluation.cover_letter_recommended =
      evaluation.decision === "recommend" ||
      evaluation.decision === "review";
  }

  evaluation.blocking_reasons =
    blockingReasons;

  evaluation.risk_flags =
    riskFlags.slice(0, 5);

  const updatedAt = $now.toUTC().toISO();

  analysis.evaluation = evaluation;
  analysis.salary_reprocessed_at = updatedAt;
  analysis.salary_reprocess_action = action;
  analysis.detected_salary_upper_bound =
    salaryUpperBound;

  vacancy.score = evaluation.score;
  vacancy.analysis_json =
    JSON.stringify(analysis);
  vacancy.updated_at = updatedAt;
  vacancy.last_error = "";

  output.push({
    json: vacancy,
  });
}

return output;

return $input.all().map((item) => {
  const vacancy = item.json;

  let analysis = {};

  try {
    analysis = JSON.parse(
      String(vacancy.analysis_json || "{}")
    );
  } catch {
    analysis = {};
  }

  const evaluation = analysis.evaluation || {};

  return {
    json: {
      vacancy_id: String(vacancy.vacancy_id || ""),
      title: String(vacancy.title || ""),
      salary: String(vacancy.salary || ""),
      detected_salary_upper_bound:
        analysis.detected_salary_upper_bound ?? null,
      salary_reprocess_action: String(
        analysis.salary_reprocess_action || ""
      ),
      score: Number(vacancy.score || 0),
      decision: String(evaluation.decision || ""),
      recommended_resume: String(
        vacancy.recommended_resume || "none"
      ),
      blocking_reasons: Array.isArray(
        evaluation.blocking_reasons
      )
        ? evaluation.blocking_reasons
        : [],
      cover_letter_recommended:
        evaluation.cover_letter_recommended === true,
    },
  };
});

const parseJson = (value) => {
  if (value && typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string' || !value.trim()) {
    return {};
  }

  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
};

const asArray = (value) => {
  return Array.isArray(value)
    ? value.map((item) => String(item)).filter(Boolean)
    : [];
};

const asBoolean = (value) => {
  return value === true || value === 'true';
};

const hardBlockingReasons = new Set([
  'salary_below_minimum',
  'location_format_mismatch',
  'vacancy_archived',
  'vacancy_unavailable',
]);

const decisionPriority = {
  recommend: 0,
  review: 1,
  reject: 2,
};

const rows = $input.all().map((item) => {
  const vacancy = { ...item.json };
  const analysis = parseJson(vacancy.analysis_json);

  const score = Number.isFinite(Number(vacancy.score))
    ? Number(vacancy.score)
    : Number(analysis.score || 0);

  const decision = String(
    analysis.decision ||
      (score >= 75 ? 'recommend' : score >= 60 ? 'review' : 'reject')
  );

  const recommendedResume = String(
    vacancy.recommended_resume ||
      analysis.recommended_resume ||
      'none'
  );

  const blockingReasons = asArray(analysis.blocking_reasons);
  const validRecommendedResume = [
    'ai_automation',
    'it_infrastructure',
  ].includes(recommendedResume);

  const hasHardBlocker = blockingReasons.some(
    (reason) => hardBlockingReasons.has(reason)
  );

  return {
    vacancy_id: String(vacancy.vacancy_id || ''),
    url: String(vacancy.url || ''),
    title: String(vacancy.title || ''),
    company: String(vacancy.company || ''),
    salary: String(vacancy.salary || ''),
    location: String(vacancy.location || ''),
    work_format: String(vacancy.work_format || ''),
    published_at: String(vacancy.published_at || ''),
    source_query: String(vacancy.source_query || ''),
    score,
    decision,
    recommended_resume: recommendedResume,
    critical_gap: asBoolean(analysis.critical_gap),
    critical_gaps: asArray(analysis.critical_gaps),
    blocking_reasons: blockingReasons,
    cover_letter_recommended:
      validRecommendedResume && !hasHardBlocker,
    matching_requirements: asArray(
      analysis.matching_requirements
    ),
    missing_requirements: asArray(
      analysis.missing_requirements
    ),
    risk_flags: asArray(analysis.risk_flags),
    summary: String(analysis.summary || '').slice(0, 600),
    eligible: validRecommendedResume && !hasHardBlocker,
  };
});

const decisionCounts = {
  recommend: 0,
  review: 0,
  reject: 0,
  other: 0,
};

for (const row of rows) {
  if (Object.hasOwn(decisionCounts, row.decision)) {
    decisionCounts[row.decision] += 1;
  } else {
    decisionCounts.other += 1;
  }
}

const eligible = rows
  .filter((row) => row.eligible)
  .sort((a, b) => {
    const decisionDifference =
      (decisionPriority[a.decision] ?? 3) -
      (decisionPriority[b.decision] ?? 3);

    if (decisionDifference !== 0) {
      return decisionDifference;
    }

    if (b.score !== a.score) {
      return b.score - a.score;
    }

    return String(b.published_at).localeCompare(
      String(a.published_at)
    );
  });

const compact = (row) => {
  const { eligible: _eligible, ...result } = row;
  return result;
};

const aiAutomation = eligible.filter(
  (row) => row.recommended_resume === 'ai_automation'
);

const itInfrastructure = eligible.filter(
  (row) => row.recommended_resume === 'it_infrastructure'
);

return [
  {
    json: {
      generated_at: $now.toUTC().toISO(),
      total_scored: rows.length,
      eligible_total: eligible.length,
      hard_blocked_total: rows.length - eligible.length,
      decision_counts: decisionCounts,
      ai_automation_eligible: aiAutomation.length,
      it_infrastructure_eligible: itInfrastructure.length,
      ai_automation_top_10: aiAutomation
        .slice(0, 10)
        .map(compact),
      it_infrastructure_top_10: itInfrastructure
        .slice(0, 10)
        .map(compact),
    },
  },
];
